using UnityEngine;
using UnityEditor;
using System.Collections.Generic;
using System.IO;
public static class BankBuilder {
 const string Dir="Assets/SCBGenerated"; static Material brick,stone,wood,glass,roof,metal,plaster; static Transform root;
 [MenuItem("Tools/SCB/Generate Bank Prefab")]
 public static void Build(){Directory.CreateDirectory(Dir);AssetDatabase.Refresh(); brick=Mat("Brick",new Color(.55f,.21f,.12f),0,.72f,0);stone=Mat("Stone",new Color(.8f,.74f,.63f),0,.65f,1);wood=Mat("Wood",new Color(.36f,.19f,.09f),0,.45f,2);glass=Mat("Glass",new Color(.22f,.39f,.49f),0,.12f,3);roof=Mat("Slate",new Color(.19f,.23f,.28f),0,.75f,1);metal=Mat("Brass",new Color(.7f,.48f,.15f),.8f,.25f,3);plaster=Mat("Plaster",new Color(.86f,.8f,.68f),0,.8f,3);
 root=new GameObject("SCB Classical Bank").transform; root.gameObject.AddComponent<BankInteraction>(); try {
 Box(root,"Foundation",new Vector3(0,.3f,0),new Vector3(24,.6f,16),stone);
 for(int i=0;i<5;i++)Box(root,"Entry step",new Vector3(0,.06f*(i+1),-9.125f+i*.25f),new Vector3(5,.12f*(i+1),.36f),stone);
 for(int floor=0;floor<2;floor++){float y=.6f+floor*4.2f; for(int side=0;side<4;side++){var wall=new GameObject("Facade "+floor+" "+side).transform;wall.SetParent(root,false);wall.localRotation=Quaternion.Euler(0,side*90,0);wall.localPosition=wall.localRotation*new Vector3(0,y,side%2==0?-7.8f:-11.8f);float width=side%2==0?24:15.28f;int bays=side%2==0?5:3;float bw=width/bays;for(int b=0;b<bays;b++){float x=-width/2+bw*(b+.5f);bool door=side==0&&floor==0&&b==2;Bay(wall,x,bw,door);}Box(wall,"Cornice",new Vector3(0,4.1f,-.13f),new Vector3(width,.2f,.65f),stone);}}
 // Upper floor leaves a 3 x 5 m stair opening on the left.
 Box(root,"Upper slab main",new Vector3(1.5f,4.65f,0),new Vector3(20.5f,.3f,15.4f),stone);Box(root,"Upper slab rear",new Vector3(-10.25f,4.65f,2.55f),new Vector3(3,.3f,10.3f),stone);
 for(int i=0;i<24;i++){float h=4.2f/24;Box(root,"Stair tread",new Vector3(-10.25f,.6f+h*(i+.5f),-7.25f+i*.21f),new Vector3(2.6f,h,.23f),wood);Box(root,"Baluster",new Vector3(-8.95f,.6f+h*(i+1)+.45f,-7.25f+i*.21f),new Vector3(.07f,.9f,.07f),wood);}
 Box(root,"Stair landing",new Vector3(-10.25f,4.65f,-2.75f),new Vector3(2.6f,.3f, .6f),stone);
 var ramp=new GameObject("Stair ramp collider");ramp.transform.SetParent(root,false);ramp.transform.localPosition=new Vector3(-10.25f,2.7f,-4.835f);ramp.transform.localRotation=Quaternion.Euler(-Mathf.Atan2(4.2f,5.04f)*Mathf.Rad2Deg,0,0);var rc=ramp.AddComponent<BoxCollider>();rc.size=new Vector3(2.5f,.12f,6.56f);rc.center=new Vector3(0,-.06f,0);
 for(int f=0;f<2;f++)for(int i=0;i<4;i++){float x=-6+i*4;Box(root,"Desk",new Vector3(x,1.1f+4.2f*f,4),new Vector3(2.6f,1,.9f),wood);Box(root,"Desk top",new Vector3(x,1.65f+4.2f*f,4),new Vector3(2.8f,.12f,1.1f),wood);}
 foreach(float x in new[]{-4.5f,-2.1f,2.1f,4.5f})Column(root,new Vector3(x,.6f,-8.15f),.32f,8.4f);
 Box(root,"Sign",new Vector3(0,8.2f,-8.28f),new Vector3(8,1.15f,.18f),Mat("Purple",new Color(.21f,.09f,.34f),0,.5f,3));
 var sign=new GameObject("Bank lettering");sign.transform.SetParent(root,false);sign.transform.localPosition=new Vector3(0,8.2f,-8.39f);var label=sign.AddComponent<TextMesh>();label.text="SIAM COMMERCIAL BANK";label.anchor=TextAnchor.MiddleCenter;label.alignment=TextAlignment.Center;label.characterSize=.22f;label.fontSize=48;label.color=new Color(.95f,.78f,.35f);
 Roof();
 // Generic fictional interior partition and round decorative vault door.
 Box(root,"Interior partition",new Vector3(8,2.55f,3),new Vector3(.2f,3.9f,8),plaster);Cylinder(root,"Vault door",new Vector3(8.2f,2.2f,4),1.2f,.18f,64,metal,Quaternion.Euler(0,0,90));
 int tris=0;foreach(var mf in root.GetComponentsInChildren<MeshFilter>())tris+=mf.sharedMesh.triangles.Length/3;
 PrefabUtility.SaveAsPrefabAsset(root.gameObject,Dir+"/SCB_Bank.prefab");Debug.Log("SCB prefab triangles: "+tris); }finally{Object.DestroyImmediate(root.gameObject);AssetDatabase.SaveAssets();AssetDatabase.Refresh();}}
 static void Bay(Transform p,float x,float w,bool door){float r=door?1.05f:.78f, sill=door?0:.65f, spring=2.55f;var panel=new GameObject("Breakable masonry").transform;panel.SetParent(p,false);panel.gameObject.AddComponent<BankDamage>();float step=.24f; // each brick is a solid fragment; openings follow semicircle
 for(int row=0;row<17;row++){float y=(row+.5f)*step;float offset=(row%2)*.22f;for(float left=-w/2-offset;left<w/2;left+=.44f){float a=Mathf.Max(left,-w/2),b=Mathf.Min(left+.44f,w/2);if(b-a<.025f)continue;float low=y-step/2;float opening=low<spring?r:Mathf.Sqrt(Mathf.Max(0,r*r-(low-spring)*(low-spring)));if(y+step/2>sill && opening>0){Brick(panel,x,a,Mathf.Min(b,-opening),y);Brick(panel,x,Mathf.Max(a,opening),b,y);}else Brick(panel,x,a,b,y);}}
 for(int j=0;j<24;j++){float a=j*Mathf.PI/24,b=(j+1)*Mathf.PI/24;Wedge(p,"Arch voussoir",new Vector3(x,spring,-.19f),r,r+.19f,a,b,.35f,stone);}
 foreach(float s in new[]{-1f,1f})Box(p,"Jamb",new Vector3(x+s*(r+.095f),(spring+sill)/2,-.19f),new Vector3(.19f,spring-sill,.35f),stone);
 if(door){var pair=new GameObject("Double door");pair.transform.SetParent(p,false);pair.AddComponent<BankDoorGroup>();for(int i=0;i<2;i++){float s=i==0?-1:1;var hinge=new GameObject("Door hinge").transform;hinge.SetParent(pair.transform,false);hinge.localPosition=new Vector3(x+s*r,0,-.02f);var d=hinge.gameObject.AddComponent<BankDoor>();d.angle=s*100;Box(hinge,"Door leaf",new Vector3(-s*r/2,spring/2,0),new Vector3(r-.025f,spring,.12f),wood);for(int k=0;k<3;k++)Box(hinge,"Raised panel",new Vector3(-s*r/2,.45f+k*.82f,-.075f),new Vector3(r*.72f,.62f,.06f),wood);Box(hinge,"Handle",new Vector3(-s*r*.85f,1.2f,-.13f),new Vector3(.06f,.28f,.08f),metal);}}
 else{Box(p,"Window glass",new Vector3(x,(sill+spring)/2,0),new Vector3(r*2,spring-sill,.045f),glass);for(int i=-1;i<=1;i++)Box(p,"Mullion",new Vector3(x+i*r*.65f,(sill+spring)/2,-.04f),new Vector3(.055f,spring-sill,.09f),metal);for(int i=0;i<3;i++)Box(p,"Transom",new Vector3(x,sill+(spring-sill)*i/3,-.04f),new Vector3(r*2,.055f,.09f),metal);}
 Wedge(p,"Fanlight",new Vector3(x,spring,0),0,r,0,Mathf.PI,.045f,glass,32);}
 static void Brick(Transform p,float x,float a,float b,float y){if(b-a>.025f)Box(p,"Brick",new Vector3(x+(a+b)/2,y,0),new Vector3(b-a,.24f,.32f),brick);}
 static void Box(Transform p,string n,Vector3 pos,Vector3 size,Material m){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(p,false);g.transform.localPosition=pos;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=m;if(n=="Brick")g.AddComponent<BankBrickImpact>();}
 static void Cylinder(Transform p,string n,Vector3 pos,float r,float height,int sides,Material m,Quaternion rot){var v=new List<Vector3>();var uv=new List<Vector2>();var t=new List<int>();for(int i=0;i<sides;i++){float a=i*2*Mathf.PI/sides,b=(i+1)*2*Mathf.PI/sides;Vector3 A=new Vector3(Mathf.Cos(a)*r,-height/2,Mathf.Sin(a)*r),B=new Vector3(Mathf.Cos(b)*r,-height/2,Mathf.Sin(b)*r),C=B+Vector3.up*height,D=A+Vector3.up*height;Quad(v,uv,t,A,D,C,B);Tri(v,uv,t,new Vector3(0,-height/2,0),A,B);Tri(v,uv,t,new Vector3(0,height/2,0),C,D);}var g=MeshObj(p,n,pos,v,uv,t,m);g.transform.localRotation=rot;}
 static void Column(Transform p,Vector3 pos,float r,float h){var v=new List<Vector3>();var uv=new List<Vector2>();var t=new List<int>();int sides=192;for(int j=0;j<12;j++)for(int i=0;i<sides;i++){Vector3 P(int a,int b){float th=a*2*Mathf.PI/sides,y=b*h/12,rr=r*(1-.13f*y/h)*(1+.07f*Mathf.Cos(th*24));return new Vector3(rr*Mathf.Cos(th),y,rr*Mathf.Sin(th));}Quad(v,uv,t,P(i,j),P(i,j+1),P(i+1,j+1),P(i+1,j));}MeshObj(p,"Fluted shaft",pos,v,uv,t,stone);for(int i=0;i<5;i++){float rr=r*(1.45f-i*.09f);Cylinder(p,"Base moulding",pos+Vector3.up*(.06f+i*.08f),rr,.09f,96,stone,Quaternion.identity);Cylinder(p,"Capital moulding",pos+Vector3.up*(h-.06f-i*.08f),rr,.09f,96,stone,Quaternion.identity);}}
 static void Wedge(Transform p,string n,Vector3 pos,float inner,float outer,float a,float b,float d,Material m,int segments=1){var v=new List<Vector3>();var u=new List<Vector2>();var t=new List<int>();Vector3 P(float r,float th,float z)=>new Vector3(r*Mathf.Cos(th),r*Mathf.Sin(th),z);for(int i=0;i<segments;i++){float x=Mathf.Lerp(a,b,(float)i/segments),y=Mathf.Lerp(a,b,(float)(i+1)/segments),f=-d/2,k=d/2;Quad(v,u,t,P(inner,x,f),P(inner,y,f),P(outer,y,f),P(outer,x,f));Quad(v,u,t,P(inner,x,k),P(outer,x,k),P(outer,y,k),P(inner,y,k));Quad(v,u,t,P(outer,x,f),P(outer,y,f),P(outer,y,k),P(outer,x,k));if(inner>0)Quad(v,u,t,P(inner,x,f),P(inner,x,k),P(inner,y,k),P(inner,y,f));}Quad(v,u,t,P(inner,a,-d/2),P(outer,a,-d/2),P(outer,a,d/2),P(inner,a,d/2));Quad(v,u,t,P(inner,b,-d/2),P(inner,b,d/2),P(outer,b,d/2),P(outer,b,-d/2));MeshObj(p,n,pos,v,u,t,m);}
 static void Roof(){var v=new List<Vector3>();var u=new List<Vector2>();var t=new List<int>();Vector3 a=new Vector3(-12.5f,9,-8.5f),b=new Vector3(12.5f,9,-8.5f),c=new Vector3(12.5f,9,8.5f),d=new Vector3(-12.5f,9,8.5f),e=new Vector3(-7,12.7f,0),f=new Vector3(7,12.7f,0);Quad(v,u,t,a,e,f,b);Quad(v,u,t,d,c,f,e);Tri(v,u,t,a,e,d);Tri(v,u,t,b,c,f);MeshObj(root,"Hip roof",Vector3.zero,v,u,t,roof);for(int side=0;side<2;side++){float s=side==0?-1:1;for(int row=0;row<24;row++){float q=(row+.5f)/24;float half=Mathf.Lerp(12.5f,7,q);for(float x=-half+.2f;x<half-.2f;x+=.42f){var g=new GameObject();g.transform.SetParent(root,false);g.transform.localPosition=new Vector3(x,9+3.7f*q+.04f,s*8.5f*(1-q));g.transform.localRotation=Quaternion.Euler(s*23.5f,0,0);Box(g.transform,"Slate tile",Vector3.zero,new Vector3(.4f,.065f,.4f),roof);}}}v.Clear();u.Clear();t.Clear();Tri(v,u,t,new Vector3(-5,9,-8.8f),new Vector3(0,11.2f,-8.8f),new Vector3(5,9,-8.8f));Tri(v,u,t,new Vector3(5,9,-8.5f),new Vector3(0,11.2f,-8.5f),new Vector3(-5,9,-8.5f));MeshObj(root,"Pediment",Vector3.zero,v,u,t,stone);}
 static void Quad(List<Vector3> v,List<Vector2> u,List<int> t,Vector3 a,Vector3 b,Vector3 c,Vector3 d){int i=v.Count;v.AddRange(new[]{a,b,c,d});u.AddRange(new[]{Vector2.zero,new Vector2(0,Vector3.Distance(a,b)),new Vector2(Vector3.Distance(b,c),Vector3.Distance(a,b)),new Vector2(Vector3.Distance(a,d),0)});t.AddRange(new[]{i,i+1,i+2,i,i+2,i+3});}
 static void Tri(List<Vector3> v,List<Vector2> u,List<int> t,Vector3 a,Vector3 b,Vector3 c){int i=v.Count;v.AddRange(new[]{a,b,c});u.AddRange(new[]{Vector2.zero,Vector2.up,Vector2.right});t.AddRange(new[]{i,i+1,i+2});}
 static GameObject MeshObj(Transform p,string n,Vector3 pos,List<Vector3> v,List<Vector2> u,List<int> t,Material m){var mesh=new Mesh();mesh.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;mesh.SetVertices(v);mesh.SetUVs(0,u);mesh.SetTriangles(t,0);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,AssetDatabase.GenerateUniqueAssetPath(Dir+"/"+n+".asset"));var g=new GameObject(n);g.transform.SetParent(p,false);g.transform.localPosition=pos;g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=m;g.AddComponent<MeshCollider>().sharedMesh=mesh;return g;}
 static Material Mat(string name,Color color,float metallic,float rough,int kind){string path=Dir+"/"+name+".mat";var old=AssetDatabase.LoadAssetAtPath<Material>(path);if(old)return old;var shader=Shader.Find("Universal Render Pipeline/Lit")??Shader.Find("Standard");var mat=new Material(shader);const int N=512;var height=new float[N*N];var albedo=new Color[N*N];var ao=new Color[N*N];var roughness=new Color[N*N];var metals=new Color[N*N];var packed=new Color[N*N];var normal=new Color[N*N];var heights=new Color[N*N];for(int y=0;y<N;y++)for(int x=0;x<N;x++){float u=(float)x/N,v=(float)y/N;float noise=Mathf.PerlinNoise(u*91,v*91),h=.5f;bool joint=false;if(kind==0||kind==1){float yy=v*(kind==0?8:4),xx=u*(kind==0?4:4)+Mathf.Floor(yy)%2*.5f;float edge=Mathf.Min(Mathf.Min(Mathf.Repeat(xx,1),1-Mathf.Repeat(xx,1)),Mathf.Min(Mathf.Repeat(yy,1),1-Mathf.Repeat(yy,1)));joint=edge<.035f;h=Mathf.Clamp01(edge*18)*.75f+noise*.12f;}else if(kind==2){h=.5f+.22f*Mathf.Sin(u*170+Mathf.PerlinNoise(u*12,v*3)*5)+noise*.1f;}else h=.5f+noise*.08f;int i=y*N+x;height[i]=h;albedo[i]=joint?new Color(.48f,.43f,.37f):color*(.82f+noise*.3f);albedo[i].a=1;float a=joint?.65f:.95f,r=Mathf.Clamp01(rough+(noise-.5f)*.1f);ao[i]=new Color(a,a,a,1);roughness[i]=new Color(r,r,r,1);metals[i]=new Color(metallic,metallic,metallic,1);packed[i]=new Color(metallic,0,0,1-r);heights[i]=new Color(h,h,h,1);}for(int y=0;y<N;y++)for(int x=0;x<N;x++){float dx=height[y*N+(x+1)%N]-height[y*N+(x+N-1)%N],dy=height[((y+1)%N)*N+x]-height[((y+N-1)%N)*N+x];Vector3 n=new Vector3(-dx*2,-dy*2,1).normalized;normal[y*N+x]=new Color(n.x*.5f+.5f,n.y*.5f+.5f,n.z*.5f+.5f,1);}var tex=Tex(name+"_Albedo",albedo,N,false,false);mat.SetTexture(mat.HasProperty("_BaseMap")?"_BaseMap":"_MainTex",tex);mat.SetTexture("_BumpMap",Tex(name+"_Normal",normal,N,true,true));mat.EnableKeyword("_NORMALMAP");mat.SetTexture("_MetallicGlossMap",Tex(name+"_MetallicSmoothness",packed,N,true,false));mat.EnableKeyword("_METALLICSPECGLOSSMAP");mat.EnableKeyword("_METALLICGLOSSMAP");mat.SetFloat("_Smoothness",1);if(mat.HasProperty("_GlossMapScale"))mat.SetFloat("_GlossMapScale",1);mat.SetTexture("_OcclusionMap",Tex(name+"_AO",ao,N,true,false));mat.EnableKeyword("_OCCLUSIONMAP");Tex(name+"_Roughness",roughness,N,true,false);Tex(name+"_Metallic",metals,N,true,false);Tex(name+"_Height",heights,N,true,false);AssetDatabase.CreateAsset(mat,path);return mat;}
 static Texture2D Tex(string name,Color[] pixels,int n,bool linear,bool normal){var t=new Texture2D(n,n,TextureFormat.RGBA32,false,linear);t.SetPixels(pixels);t.Apply();string p=Dir+"/"+name+".png";File.WriteAllBytes(p,t.EncodeToPNG());Object.DestroyImmediate(t);AssetDatabase.ImportAsset(p,ImportAssetOptions.ForceSynchronousImport);var imp=(TextureImporter)AssetImporter.GetAtPath(p);imp.sRGBTexture=!linear;imp.textureType=normal?TextureImporterType.NormalMap:TextureImporterType.Default;imp.wrapMode=TextureWrapMode.Repeat;imp.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(p);}
}
